const tabId = 1148881640;

const answers = await browserjs(tabId, () => {
  const results = {};
  const buttons = Array.from(document.querySelectorAll('button, [role="tab"]'));

  // Find "What do I do if I lost an item on the bus?" and "What about lost luggage?"
  const targetButtons = buttons.filter(b => 
    b.textContent.includes("What do I do if I lost an item on the bus") ||
    b.textContent.includes("What about lost luggage")
  );

  targetButtons.forEach(btn => {
    btn.click();
  });

  return targetButtons.map(b => b.textContent.trim());
});
console.log("Clicked:", answers);

await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1000 });

const textData = await browserjs(tabId, () => {
  const items = [];
  const headings = Array.from(document.querySelectorAll('h3, h4'));
  headings.forEach(h => {
    if (h.textContent.includes("lost an item") || h.textContent.includes("lost luggage")) {
      let content = "";
      let curr = h.parentElement;
      while (curr && !curr.querySelector('p')) {
        curr = curr.parentElement;
      }
      if (curr) {
        content = curr.innerText;
      }
      items.push({ heading: h.textContent.trim(), content });
    }
  });
  return items;
});
console.log(JSON.stringify(textData, null, 2));

